function report(findings, title) {
  const relevant = findings.filter((f) => f.level === 'ERROR' || f.level === 'WARN');
  if (!relevant.length) return [];
  return [`${title}:`, ...limit(common.formatFindings(relevant).split('\n'))];
}

function fileChecks(rel, text) {
