if (declared && (!target || !m.binds.startsWith(target) || !/—\s*\S.{10,}/.test(m.binds))) fail(m.manifestPath, `binds must be "none" or "${target} — <reason>"`);
const evidence = [];
for (const p of moduleFiles(m)) {
