const SECTION_REF = /(?:`([^`]+)`|\b(CLAUDE\.md|(?:\.claude\/)?(?:rules|skills)\/[\w./-]+\.md|[a-z][a-z0-9]*(?:-[a-z0-9]+)+))\s*§\s*([^.;,)\n—'"`\\]+?)(?=\s*(?:[.;,)\n—'"`\\]|\(|$| and §| and `))/g;
