      if (/^-(f|file)$/.test(w)) return null;
      if (/^-(executionpolicy|ep|ex|windowstyle|w|configurationname|workingdirectory|wd)$/.test(w)) {
        i += 1;
        continue;
      }
      if (!w.startsWith('-')) return exe === 'powershell' ? words.slice(i).join(' ') : null;
    }
    return null;
  }
  return null;

